    "title": "Standard Operating Procedure SOP-STK-03: Timber & Warehouse Management",
    "objective": "Execute protocol SOP-STK-03 to maintain 99.8% inventory accuracy and eliminate material delays for furniture manufacturing.",
    "prerequisites": "Rugged barcode scanner; active Odoo inventory session; verified warehouse bin locations.",
